# Холодный старт + «Первый час»
from kit import S, A, P, G, card, B

def M(**o):            # карта мира
    cam = o.pop('cam', None); push = o.pop('push', 1.08); tags = o.pop('tags', []); big = o.pop('big', None); kw = {}
    if big: kw['big'] = big
    return S('world', [], [], tags, cam, setOpts=o, push=push, **kw)
def BIG(text, sub=None, set='black', col='#ffffff', props=(), size=170, dim=None, **kw):
    b = dict(t=text, size=size, col=col, at=0.05)
    if sub: b['sub'] = sub
    extra = dict(dim=dim) if dim else {}
    return S(set, [], list(props), [], None, big=[b], **extra, **kw)
def FACE(c, set='plain', expr='neutral', x=960, s=1.0, z=2.4, tags=(), props=(), setOpts=None, **a):
    hy = 930 - 240 * s
    return S(set, [A(c, x, 930, s=s, expr=expr, **a)], list(props), list(tags), [[0, x, hy + 40, z], ['end', x, hy + 30, z * 1.08]], setOpts=setOpts or {})
US, SU = '#3a6ad9', '#c8423a'
SUiso = {'RUS': SU, 'UKR': SU, 'BLR': SU, 'KAZ': SU, 'UZB': SU, 'TKM': SU, 'KGZ': SU, 'TJK': SU, 'GEO': SU, 'ARM': SU, 'AZE': SU, 'LTU': SU, 'LVA': SU, 'EST': SU, 'MDA': SU}
NH = [-140, 10, 80, 78]     # северное полушарие
def arcs5(at, d=1.4): return [[-100 + i * 6, 38 + i * 2, 40 + i * 12, 55 + (i % 2) * 3, '#ff4a3a', at, d + i * 0.15] for i in range(5)]

